/// <summary>
/// METPurchLineCopyFromSource extension class to copy custom field
/// </summary>
[ExtensionOf(classStr(PurchLineCopyFromSource))]
final class METPurchLineCopyFromSource_Extension
{
}

Method.Source:
/// <summary>
/// Updates the <c>PurchLine</c> after the copy and creation.
/// </summary>
/// <param name = "_purchLine">A purchase order line that has been copied.</param>
/// <param name = "_purchTable">The purchase order for the purchase order line.</param>
public void updateCopiedLine(PurchLine _purchLine, PurchTable _purchTable)
{
    if (_purchLine.RecId && this.retrieveSource())
    {
        METPurchLine metPurchLineFrom = METPurchLine::find(this.retrieveSource().RecId);
        METPurchaseWMSFactor purchaseWmsFactor = metPurchLineFrom.PurchaseWMSFactor;
        CostPriceNonMonetary inventItemBasePrice = metPurchLineFrom.InventItemBasePrice;

        if (purchaseWmsFactor != 0 || inventItemBasePrice != 0)
        {
            METPurchLine metPurchLine = METPurchLine::find(_purchLine.RecId, true);

            if (metPurchLine)
            {
                try
                {
                    if (purchaseWmsFactor != 0)
                    {
                        metPurchLine.PurchaseWMSFactor = purchaseWmsFactor;
                    }

                    metPurchLine.InventItemBasePrice = inventItemBasePrice;

                    metPurchLine.update();
                }
                catch
                {
                    throw;
                }
            }
        }
    }

    next updateCopiedLine(_purchLine, _purchTable);
}
